/* Place the existing per-block view switch within its first panel header. */
.panel-header-bar {
  display: flex;
  align-items: center;
  min-width: 0;
  background: linear-gradient(90deg, #2d2d44 0%, #3d3d5c 50%, #2d2d44 100%);
  border-bottom: 1px solid #8b7355;
}
.panel-header-bar > button.panel-header {
  flex: 1;
  width: auto;
  min-width: 0;
  border-bottom: 0;
  background: transparent;
}
.panel-header-bar > button.panel-header:hover {
  background: rgba(255,255,255,.025);
}
.panel-header-bar .panel-title {
  min-width: 0;
  overflow-wrap: anywhere;
}
.panel-header-bar > .view-toolbar {
  flex: 0 0 auto;
  margin: 0;
  gap: 6px;
  padding-right: 12px;
  font-size: .8em;
}
.panel-header-bar .view-mode-button {
  min-height: 36px;
  padding: 4px 10px;
}
@media (max-width: 480px) {
  .panel-header-bar.has-view-controls .panel-expand-hint { display: none; }
  .panel-header-bar.has-view-controls > .panel-header { gap: 6px; padding-right: 7px; }
  .panel-header-bar > .view-toolbar { gap: 4px; padding-right: 8px; }
  .panel-header-bar .view-mode-button { padding: 4px 7px; }
}

