      // Display names are derived only after each section's own rows are complete.
      // Original headings stay unchanged for raw-output matching and navigation.
      sections.forEach(section => {
        section.displayTitle = section.title;
        const actor = actorFromActionRows(section.stageType, section.rows);
        if (actor) section.displayTitle = actor + ': ' + section.title;
      });
      return { sections };
    }

    function beautifyRow(row, skipOverviewFields = false) {
      // Recognize these fields in source text before any HTML is generated.
      // Protect them from later label replacements, then restore their own markup.
      const overviewFields = [];
      let fieldMarker = '\uE000OVERVIEW';
      while (row.includes(fieldMarker)) fieldMarker += '_';
      const protectedRow = skipOverviewFields ? row : row.replace(
        /(^|\|)(\s*)((?:坐标范围|坐標範圍|座標範圍)|(?:常驻|常駐)(?:\s*[(（][^()（）|]*[)）])?)\s*[:：]\s*([^|]*)/g,
        (match, prefix, spacing, label, rawValue) => {
          const isBounds = /^(?:坐标范围|坐標範圍|座標範圍)$/.test(label);
          const value = rawValue.trim();
          const isEmpty = !isBounds && /^(?:无|無|暂无|暫無|无常驻(?:效果)?|無常駐(?:效果)?|[-—])$/.test(value);
          const icon = isBounds ? 'fa-ruler-horizontal' : 'fa-shield-halved';
          const classes = 'overview-field ' + (isBounds ? 'overview-coordinate' : 'overview-permanent') + (isEmpty ? ' overview-empty' : '');
          const formattedValue = isBounds ? _.escape(value) : beautifyRow(value, true);
          const fieldHtml = '<span class="' + classes + '"><span class="overview-field-label"><i class="fa-solid ' + icon + '" aria-hidden="true"></i> ' + _.escape(label) + ':</span> <span class="overview-field-value">' + formattedValue + '</span></span>';
          const token = fieldMarker + overviewFields.length + '\uE001';
          overviewFields.push({ token, html: fieldHtml });
          return prefix + spacing + token + ' ';
        }
      );
      let html = _.escape(protectedRow);

      const labels = {
        round:        '(?:回合|回合數)',
        environment:  '(?:环境|環境)',
        sequence:     '(?:序列)',
        type:         '(?:类型|類型)',
        industry:     '(?:行业|行業)',
        target:       '(?:目标|目標)',
        role:         '(?:角色)',
        attacker:     '(?:攻方)',
        defender:     '(?:守方)',
        object:       '(?:对象|對象)',
        contest:      '(?:对抗|對抗)',
        move:         '(?:招式)',
        weapon:       '(?:所使武器)',
        consume:      '(?:消耗)',
        execute:      '(?:执行|執行)',
        cert:         '(?:认证|認證)',
        coreStat:     '(?:核心属性|核心屬性)',
        quality:      '(?:品质|品質)',
        status:       '(?:状态|狀態)',
        statusApply:  '(?:状态施加|狀態施加)',
        stateSummary: '(?:状态结算|狀態結算)',
        checkResult:  '(?:检定结果|檢定結果)',
        result:       '(?:结果|結果)',
        intent:       '(?:意图|意圖)',
        battleResult: '(?:战果|戰果)',
        effect:       '(?:效果)',
        statusEffect: '(?:状态效果|狀態效果)',
        resourcePreview: '(?:资源预检|資源預檢)',
        resourceCost: '(?:资源消耗|資源消耗)',
        settlement: '(?:结算状态|結算狀態)',
        expDetail: '(?:经验明细|經驗明細)',
        expBasis: '(?:经验依据|經驗依據)',
        expTotal: '(?:EXP合计)',
        expActual: '(?:上限后实得EXP|上限後實得EXP)',
        reward: '(?:奖励|獎勵)',
        materials:    '(?:投入物)',
        input:        '(?:投入)',
        loss:         '(?:损失|損失)',
        outputList:   '(?:产出列表|產出列表)',
        eta:          '(?:预估时间|預估時間)',
        timeCost:     '(?:时间消耗|時間消耗)',
        batchCheck:   '(?:批量检查|批量檢查)',
        qualityCheck: '(?:品质要求检查\\(仅半成品\\/成品\\)|品質要求檢查\\(僅半成品\\/成品\\))',
        licenseCheck: '(?:管制投入物检查\\(仅半成品\\/成品\\)|管制投入物檢查\\(僅半成品\\/成品\\))'
      };

      const wrapLabeledValue = (label, regex, className, icon, color = null, extraClass = '') => {
        html = html.replace(regex, (m, value) => {
          const displayLabel = _.escape(label.replace(/\(\?:|\)/g, '').split('|')[0]);
          const style = color ? ` style="background:${color.background};color:${color.color};"` : '';
          const classes = [className, extraClass].filter(Boolean).join(' ');
          return `${displayLabel} <span class="${classes}"${style}><i class="${icon}"></i> ${value.trim()}</span>`;
        });
      };

      const formatResourceTokens = (value) => value.replace(
        /\b(HP|MP|SP)\s*\[?\s*(\d+(?:\.\d+)?)(?:\s*\/\s*(\d+(?:\.\d+)?))?(?:\s*([（(]\s*\d+(?:\.\d+)?\s*%[)）]))?(?:\s*\])?(?![\d./])/g,
        (match, type, current, max, percentText, offset, source) => {
          const config = {
            HP: { tag: 'hp', icon: 'heart', threshold: 50 },
            MP: { tag: 'mp', icon: 'droplet', threshold: 35 },
            SP: { tag: 'sp', icon: 'bolt', threshold: 35 }
          }[type];

          // A cost may span several pipe-delimited resource fields.
          const precedingFields = source.slice(0, offset).split('|');
          let isCost = false;
          for (let i = precedingFields.length - 1; i >= 0; i--) {
            const label = precedingFields[i].match(/^\s*([^:：]+)[:：]/);
            if (!label) continue;
            isCost = /^(?:消耗|消耗数值|消耗數值|资源消耗|資源消耗)$/.test(label[1].trim());
            break;
          }

          let colorClass = `tag-${config.tag}`;
          let meterStyle = '';
          let hasMeter = false;
          if (max !== undefined) {
            const maximum = Number(max);
            if (maximum > 0) {
              const percent = Number(current) / maximum * 100;
              if (!isCost && percent <= config.threshold) colorClass += '-low';
              if (!isCost && Number.isFinite(percent)) {
                hasMeter = true;
                meterStyle = ` style="--resource-ratio:${Math.max(0, Math.min(100, percent)) / 100};"`;
              }
            } else {
              colorClass = 'tag-resource-neutral';
            }
          }

          const amount = max === undefined ? current : `${current}/${max}`;
          const text = `${type} ${amount}${percentText || ''}`;
          return `<span class="tag ${colorClass} tag-resource${hasMeter ? ' resource-meter' : ''}"${meterStyle}><i class="fa-solid fa-${config.icon}"></i> ${text}</span>`;
        }
      );

      // ===== HP / MP / SP =====
      html = formatResourceTokens(html);

      // ===== 五维属性 =====
      html = html.replace(/(^|[\s|（(:：,，;；=＝+＋×*÷\/−-])(力)\[?(\d+)\]?/g, (m, sep, _, val) =>
        `${sep}<span class="stat stat-str"><i class="fa-solid fa-dumbbell"></i> 力量${val}</span>`);
      html = html.replace(/(^|[\s|（(:：,，;；=＝+＋×*÷\/−-])(敏)\[?(\d+)\]?/g, (m, sep, _, val) =>
        `${sep}<span class="stat stat-agi"><i class="fa-solid fa-feather-pointed"></i> 敏捷${val}</span>`);
      html = html.replace(/(^|[\s|（(:：,，;；=＝+＋×*÷\/−-])(体)\[?(\d+)\]?/g, (m, sep, _, val) =>
        `${sep}<span class="stat stat-con"><i class="fa-solid fa-shield-heart"></i> 体质${val}</span>`);
      html = html.replace(/(^|[\s|（(:：,，;；=＝+＋×*÷\/−-])(智)\[?(\d+)\]?/g, (m, sep, _, val) =>
        `${sep}<span class="stat stat-int"><i class="fa-solid fa-brain"></i> 智力${val}</span>`);
      html = html.replace(/(^|[\s|（(:：,，;；=＝+＋×*÷\/−-])(精)\[?(\d+)\]?/g, (m, sep, _, val) =>
        `${sep}<span class="stat stat-spi"><i class="fa-solid fa-eye"></i> 精神${val}</span>`);

      // ===== 基础标签 =====
      html = html.replace(new RegExp(`${labels.round}:\\s*(\\d+)`, 'g'), (m, num) =>
        `<span class="tag tag-round"><i class="fa-solid fa-rotate"></i> 回合 ${num}</span>`);
      html = html.replace(new RegExp(`${labels.environment}:\\s*([^|]+)`, 'g'), (m, env) =>
        `环境: <span class="tag tag-env"><i class="fa-solid fa-location-dot"></i> ${env.trim()}</span>`);
      html = html.replace(new RegExp(`${labels.sequence}:\\s*([^|]+)`, 'g'), (m, seq) =>
        `序列: <span class="tag tag-round"><i class="fa-solid fa-list-ol"></i> ${seq.trim()}</span>`);
      html = html.replace(/(^|\|\s*)(消耗|消耗數值):\s*([^|]*(?:\|\s*(?:<span class="tag tag-(?:hp|mp|sp)"[^>]*>.*?<\/span>|(?:HP|MP|SP)\s*\[[^\]]+\]))*)/g,
        (m, prefix, _label, value) => `${prefix}<span class="field-label">消耗:</span> ${value.trim()}`);
      html = html.replace(new RegExp(`${labels.resourcePreview}:\\s*([^|]*(?:\\|\\s*(?:<span class="tag tag-(?:hp|mp|sp)"[^>]*>.*?<\\/span>|(?:HP|MP|SP)\\s*\\[[^\\]]+\\]))*)`, 'g'),
        (m, value) => `<span class="field-label">资源预检:</span> ${value.trim()}`);
      html = html.replace(new RegExp(`${labels.resourceCost}:\\s*([^|]*(?:\\s+(?:<span class="tag tag-(?:hp|mp|sp)"[^>]*>.*?<\\/span>|(?:HP|MP|SP)\\s*\\[[^\\]]+\\]))*)`, 'g'),
        (m, value) => `<span class="field-label">资源消耗:</span> ${value.trim()}`);

      // ===== 类型标签（战斗/制作） =====
      html = html.replace(new RegExp(`${labels.type}:\\s*([^|]+)`, 'g'), (m, type) => {
        const value = type.trim();
        const mapping = {
          '锻造':   { icon: 'fa-solid fa-hammer',         background: '#c53030', color: '#fff' },
          '炼金':   { icon: 'fa-solid fa-flask',          background: '#805ad5', color: '#fff' },
          '烹饪':   { icon: 'fa-solid fa-utensils',       background: '#dd6b20', color: '#fff' },
          '裁缝':   { icon: 'fa-solid fa-scissors',       background: '#319795', color: '#fff' },
          '基础加工': { icon: 'fa-solid fa-gears',        background: '#4a5568', color: '#fff' },
          '半成品': { icon: 'fa-solid fa-cubes',          background: '#2b6cb0', color: '#fff' },
          '成品':   { icon: 'fa-solid fa-box-open',       background: '#2f855a', color: '#fff' },
          '逃跑':   { icon: 'fa-solid fa-person-running', background: '#975a16', color: '#fff' }
        };
        const style = mapping[value];
        if (style) {
          return `类型: <span class="tag" style="background:${style.background};color:${style.color};"><i class="${style.icon}"></i> ${value}</span>`;
        }
        return `类型: <span class="tag tag-type"><i class="fa-solid fa-tag"></i> ${value}</span>`;
      });

      // ===== wrapLabeledValue 调用 =====
      wrapLabeledValue('行业:', new RegExp(`${labels.industry}:\\s*([^|]+)`, 'g'),   'tag tag-type', 'fa-solid fa-industry',        { background: '#744210', color: '#fff' });
      wrapLabeledValue('目标:', new RegExp(`${labels.target}:\\s*([^|]+)`, 'g'),     'tag tag-env',  'fa-solid fa-bullseye',         { background: '#2c5282', color: '#bee3f8' });
      wrapLabeledValue('角色:', new RegExp(`${labels.role}:\\s*([^|]+)`, 'g'),       'tag tag-env',  'fa-solid fa-user',             { background: '#285e61', color: '#e6fffa' });
      wrapLabeledValue('攻方:', new RegExp(`${labels.attacker}[:：]\\s*([^|]+)`, 'g'), 'tag tag-combat-role', 'fa-solid fa-hand-fist');
      wrapLabeledValue('守方:', new RegExp(`${labels.defender}[:：]\\s*([^|]+)`, 'g'), 'tag tag-combat-role', 'fa-solid fa-shield');
      wrapLabeledValue('对象:', new RegExp(`${labels.object}:\\s*([^|]+)`, 'g'),     'tag tag-env',  'fa-solid fa-crosshairs',       { background: '#4a5568', color: '#fff' });
      wrapLabeledValue('对抗:', new RegExp(`${labels.contest}:\\s*([^|]+)`, 'g'),    'tag tag-type', 'fa-solid fa-scale-balanced',   { background: '#553c9a', color: '#fff' });
      wrapLabeledValue('招式:', new RegExp(`${labels.move}:\\s*([^|]+)`, 'g'),       'tag tag-type', 'fa-solid fa-wand-sparkles',    { background: '#553c9a', color: '#fff' });
      wrapLabeledValue('所使武器:', new RegExp(`${labels.weapon}:\\s*([^|]+)`, 'g'), 'tag tag-type', 'fa-solid fa-khanda',            { background: '#744210', color: '#fff' });
      wrapLabeledValue('执行:', new RegExp(`${labels.execute}:\\s*([^|]+)`, 'g'),    'tag tag-type', 'fa-solid fa-play',             { background: '#2d3748', color: '#fff' });
      wrapLabeledValue('认证:', new RegExp(`${labels.cert}:\\s*([^|]+)`, 'g'),       'tag tag-type', 'fa-solid fa-certificate',      { background: '#975a16', color: '#fff' });

      // ===== 核心属性 =====
      html = html.replace(new RegExp(`${labels.coreStat}:\\s*(力量)`, 'g'), (m, g1) => `核心属性: <span class="stat stat-str">${g1}</span>`);
      html = html.replace(new RegExp(`${labels.coreStat}:\\s*(智力)`, 'g'), (m, g1) => `核心属性: <span class="stat stat-int">${g1}</span>`);
      html = html.replace(new RegExp(`${labels.coreStat}:\\s*(精神)`, 'g'), (m, g1) => `核心属性: <span class="stat stat-spi">${g1}</span>`);
      html = html.replace(new RegExp(`${labels.coreStat}:\\s*(敏捷)`, 'g'), (m, g1) => `核心属性: <span class="stat stat-agi">${g1}</span>`);
      html = html.replace(new RegExp(`${labels.coreStat}:\\s*(力量|智力|精神|敏捷)`, 'g'), (m, g1) => `核心属性: <span class="stat">${g1}</span>`);

      // ===== 品质 =====
      html = html.replace(new RegExp(`${labels.quality}:\\s*(普通)`, 'g'),       (m, g1) => `品质: <span style="color:#a0aec0;font-weight:600;">${g1}</span>`);
      html = html.replace(new RegExp(`${labels.quality}:\\s*(優良|优良)`, 'g'),  (m, g1) => `品质: <span style="color:#68d391;font-weight:600;">${g1}</span>`);
      html = html.replace(new RegExp(`${labels.quality}:\\s*(稀有)`, 'g'),       (m, g1) => `品质: <span style="color:#63b3ed;font-weight:600;">${g1}</span>`);
      html = html.replace(new RegExp(`${labels.quality}:\\s*(史詩|史诗)`, 'g'),  (m, g1) => `品质: <span style="color:#b794f4;font-weight:600;">${g1}</span>`);
      html = html.replace(new RegExp(`${labels.quality}:\\s*(傳說|传说)`, 'g'),  (m, g1) => `品质: <span style="color:#f6ad55;font-weight:600;">${g1}</span>`);
      html = html.replace(new RegExp(`${labels.quality}:\\s*(神話|神话)`, 'g'),  (m, g1) => `品质: <span style="color:#fc8181;font-weight:600;text-shadow:0 0 8px rgba(252,129,129,0.5);">${g1}</span>`);

      // ===== 状态 =====
      html = html.replace(new RegExp(`(^|\\|\\s*)${labels.status}:\\s*(制作失败|製作失敗|制作成功|製作成功|充足|不足(?:\\(终止\\)|\\(終止\\))?)`, 'g'), (m, prefix, state) => {
        const isBad = /失败|失敗|不足/.test(state);
        return `${prefix}状态: <span style="color:${isBad ? '#fc8181' : '#68d391'};font-weight:700;">${_.escape(state)}</span>`;
      });
      html = html.replace(new RegExp(`(^|\\|\\s*)${labels.status}:\\s*([^|]+)`, 'g'), (match, prefix, states) => {
        if (/制作失败|製作失敗|制作成功|製作成功|充足|不足/.test(states)) return match;
        const stateList = states.split(/[，,]/).map(s => s.trim()).filter(Boolean);
        const stateHtml = stateList.map(state => {
          const durationMatch = state.match(/\(([^()]*?回合)\)/);
          const duration = durationMatch ? ` (${durationMatch[1]})` : '';
          const stateName = state.replace(/\([^()]*?回合\)/, '').trim();
          return `<span class="status-effect">${stateName}${duration}</span>`;
        }).join('');
        return `${prefix}<span class="status-label">状态:</span> ${stateHtml}`;
      });
      html = html.replace(new RegExp(`${labels.statusApply}\\s*[(（]([^()（）]+)[)）]\\s*[:：]\\s*([^|]+)`, 'g'), (m, effectName, result) =>
        `<span class="field-label">状态施加</span><span class="tag tag-flex" style="background:#553c9a;color:#fff;"><i class="fa-solid fa-burst"></i> ${effectName}</span>: <span style="color:#d6bcfa;">${result.trim()}</span>`);
      html = html.replace(new RegExp(`${labels.stateSummary}:\\s*([^|]+)`, 'g'), (m, summary) =>
        `<span class="field-label">状态结算:</span> <span style="color:#e9d8fd;">${summary.trim()}</span>`);

      // ===== 检定结果 =====
      html = html.replace(new RegExp(`${labels.checkResult}:\\s*(大失败|大失敗)`, 'g'), (m, g1) => `检定结果: <span style="color:#e53e3e;font-weight:700;"><i class="fa-solid fa-skull-crossbones"></i> ${g1}</span>`);
      html = html.replace(new RegExp(`${labels.checkResult}:\\s*(失败|失敗)`, 'g'),     (m, g1) => `检定结果: <span style="color:#fc8181;font-weight:700;"><i class="fa-solid fa-times"></i> ${g1}</span>`);
      html = html.replace(new RegExp(`${labels.checkResult}:\\s*(成功)`, 'g'),           (m, g1) => `检定结果: <span style="color:#68d391;font-weight:700;"><i class="fa-solid fa-check"></i> ${g1}</span>`);
      html = html.replace(new RegExp(`${labels.checkResult}:\\s*(精益求精)`, 'g'),       (m, g1) => `检定结果: <span style="color:#ffd700;font-weight:700;text-shadow:0 0 8px rgba(255,215,0,0.5);"><i class="fa-solid fa-star"></i> ${g1}</span>`);

      // ===== 结果/战果 =====
      html = html.replace(new RegExp(`${labels.result}:\\s*(胜利|勝利|逃跑成功)`, 'g'), (m, g1) =>
        `结果: <span style="color:#48bb78;font-weight:700;"><i class="fa-solid fa-trophy"></i> ${_.escape(g1)}</span>`);
      html = html.replace(new RegExp(`${labels.result}:\\s*(失败|失敗|逃跑失败)`, 'g'), (m, g1) =>
        `结果: <span style="color:#fc8181;font-weight:700;"><i class="fa-solid fa-skull"></i> ${_.escape(g1)}</span>`);
      html = html.replace(new RegExp(`${labels.battleResult}:\\s*([^|]+)`, 'g'), (m, val) =>
        `战果: <span style="color:#e2e8f0;font-style:italic;">${val.trim()}</span>`);
      html = html.replace(new RegExp(`${labels.settlement}:\\s*([^|]+)`, 'g'), (m, val) =>
        `结算状态: <span style="color:#fbd38d;font-weight:600;">${val.trim()}</span>`);

      html = html.replace(new RegExp(`${labels.expDetail}:\\s*([^|]+)`, 'g'), (m, val) =>
        `经验明细: <span style="color:#e2e8f0;line-height:1.5;">${val.trim()}</span>`);
      html = html.replace(new RegExp(`${labels.expBasis}:\\s*([^|]+)`, 'g'), (m, val) =>
        `经验依据: <span style="color:#fbd38d;">${val.trim()}</span>`);
      html = html.replace(new RegExp(`${labels.expTotal}:\\s*(\\[[^\\]]+\\]|\\d+)`, 'g'), (m, val) =>
        `EXP合计: <span style="color:#f6e05e;font-weight:700;"><i class="fa-solid fa-calculator"></i> ${val}</span>`);
      html = html.replace(new RegExp(`${labels.expActual}:\\s*(\\[[^\\]]+\\]|\\d+)`, 'g'), (m, val) =>
        `上限后实得EXP: <span style="color:#ffd700;font-weight:700;"><i class="fa-solid fa-arrow-trend-up"></i> ${val}</span>`);

      // ===== 意图 =====
      html = html.replace(new RegExp(`${labels.intent}:\\s*([^|]+)`, 'g'), (m, val) =>
        `意图: <span style="color:#fbd38d;">${val.trim()}</span>`);

      // ===== 效果/状态效果 =====
      wrapLabeledValue('状态效果:', new RegExp(`${labels.statusEffect}:\\s*([^|]+)`, 'g'), 'tag tag-type', 'fa-solid fa-circle-nodes',  { background: '#44337a', color: '#e9d8fd' }, 'tag-detail');
      html = html.replace(new RegExp(`(^|\\|\\s*)${labels.effect}:\\s*([^|]+)`, 'g'), (m, prefix, value) =>
        `${prefix}效果: <span class="tag tag-type tag-detail" style="background:#2d3748;color:#e2e8f0;"><i class="fa-solid fa-star-of-david"></i> ${value.trim()}</span>`);

      // ===== 生产制作专属 =====
      wrapLabeledValue('投入物:', new RegExp(`${labels.materials}:\\s*([^|]+)`, 'g'),  'tag tag-sp', 'fa-solid fa-boxes-stacked', { background: '#276749', color: '#fff' }, 'tag-detail');
      wrapLabeledValue('投入:',   new RegExp(`${labels.input}:\\s*([^|]+)`, 'g'),      'tag tag-sp', 'fa-solid fa-box',           { background: '#276749', color: '#fff' }, 'tag-detail');
      wrapLabeledValue('损失:',   new RegExp(`${labels.loss}:\\s*([^|]+)`, 'g'),       'tag tag-hp', 'fa-solid fa-box-open',      { background: '#9b2c2c', color: '#fff' }, 'tag-detail');
      wrapLabeledValue('产出列表:', new RegExp(`${labels.outputList}:\\s*([^|]+)`, 'g'), 'tag tag-sp', 'fa-solid fa-box-open',     { background: '#2f855a', color: '#fff' }, 'tag-detail');
      wrapLabeledValue('预估时间:', new RegExp(`${labels.eta}:\\s*([^|]+)`, 'g'),      'tag tag-round', 'fa-solid fa-clock',      { background: '#4a5568', color: '#fff' }, 'tag-detail');
      wrapLabeledValue('时间消耗:', new RegExp(`${labels.timeCost}:\\s*([^|]+)`, 'g'), 'tag tag-round', 'fa-solid fa-hourglass',  { background: '#4a5568', color: '#fff' }, 'tag-detail');
      wrapLabeledValue('批量检查:', new RegExp(`${labels.batchCheck}:\\s*([^|]+)`, 'g'), 'tag tag-type', 'fa-solid fa-layer-group', { background: '#2b6cb0', color: '#fff' });
      wrapLabeledValue('品质要求检查(仅半成品/成品):', new RegExp(`${labels.qualityCheck}:\\s*([^|]+)`, 'g'), 'tag tag-type', 'fa-solid fa-medal',          { background: '#2c5282', color: '#fff' }, 'tag-detail');
      wrapLabeledValue('管制投入物检查(仅半成品/成品):', new RegExp(`${labels.licenseCheck}:\\s*([^|]+)`, 'g'), 'tag tag-type', 'fa-solid fa-scale-balanced', { background: '#744210', color: '#fff' }, 'tag-detail');

      // ===== 生死状态 =====
      html = html.replace(/死亡\/毁坏|死亡\/毀壞/g,
        '<span style="color:#e53e3e;font-weight:700;"><i class="fa-solid fa-skull"></i> 死亡/毁坏</span>');
      html = html.replace(/未死\/存活/g,
        '<span style="color:#68d391;font-weight:700;"><i class="fa-solid fa-heart-pulse"></i> 未死/存活</span>');

      // ===== EXP / FP =====
      html = html.replace(/EXP\s*\+(\d+)/g, (m, val) =>
        `<span style="color:#ffd700;font-weight:700;"><i class="fa-solid fa-star"></i> EXP +${val}</span>`);
      html = html.replace(/FP\s*\+(\d+)/g, (m, val) =>
        `<span style="color:#90cdf4;font-weight:700;"><i class="fa-solid fa-gem"></i> FP +${val}</span>`);
      html = html.replace(new RegExp(`${labels.reward}:\\s*`, 'g'),
        '<span class="field-label">奖励:</span> ');

      // Emphasize reported results without recalculating any combat values.
      html = html.replace(/(^|\|\s*)(最终伤害|最終傷害)\s*[:：]\s*(\[?\s*\d+(?:\.\d+)?\s*\]?)/g,
        (m, prefix, label, value) => `${prefix}${label}: <strong class="final-damage-value">${value.trim()}</strong>`);
      html = html.replace(/(^|\|\s*)(结果|結果)\s*[:：]\s*(\[?(?:超暴击|强暴击|平暴击|超暴擊|強暴擊|平暴擊|有效|勉强|勉強|擦伤|擦傷|失手)\]?)/g,
        (m, prefix, label, value) => `${prefix}${label}: <strong class="attack-rating">${value}</strong>`);

      // ===== 箭头文本统一：避免显示 HTML 实体 =====
      html = html.replace(/-&gt;/g, '->');

      for (const field of overviewFields) html = html.split(field.token).join(field.html);
      return html;
    }

    // DLC 1.4.6 (1): faction colors follow explicit labels in each snapshot.
    function axisCleanName(value) {
      const text = String(value).trim();
      return /^[\[【][^\[\]【】]+[\]】]$/.test(text) ? text.slice(1, -1).trim() : text;
    }

    function parseAxisUnits(row) {
      const field = row.match(/位置[轴軸]\s*[:：]\s*([^|]*)/);
      if (!field) return [];
      const text = field[1];
      // Locate the position first. Optional facing and notes must not determine
      // whether this unit exists, or a later unit could absorb its name.
      const pattern = /[（(]\s*位置\s*[\[【]?\s*([+-]?\d+)\s*[\]】]?\s*(?=[,，;；)）])/g;
      const units = [];
      let end = 0;
      for (const match of text.matchAll(pattern)) {
        if (match.index < end) continue;
        let depth = 1, close = match.index + match[0].length;
        for (; close < text.length; close++) {
          if (/[（(]/.test(text[close])) depth++;
          else if (/[)）]/.test(text[close]) && --depth === 0) break;
        }
        if (depth !== 0) continue;
        const markedName = axisCleanName(text.slice(end, match.index).replace(/^\s*(?:[—–]+|->|→|[,，;；])?\s*/, ''));
        const details = text.slice(match.index + match[0].length, close);
        end = close + 1;
        const factionMatch = markedName.match(/^【\s*(蓝方|藍方|红方|紅方)\s*】\s*/);
        const faction = factionMatch ? (/^[蓝藍]/.test(factionMatch[1]) ? 'blue' : 'red') : null;
        const factionLabel = faction === 'blue' ? '蓝方' : faction === 'red' ? '红方' : '';
        const fullName = axisCleanName(factionMatch ? markedName.slice(factionMatch[0].length) : markedName);
        if (!fullName || !Number.isSafeInteger(Number(match[1]))) continue;
        const mcMatch = fullName.match(/[（(]\s*MC\s*[=＝]\s*(\d+(?:\.\d+)?)\s*[)）]/i);
        const countMatch = fullName.match(/[（(]\s*(\d+)\s*\/\s*(\d+)\s*[)）]/);
        let name = fullName.replace(/[（(]\s*MC\s*[=＝]\s*\d+(?:\.\d+)?\s*[)）]/ig, '')
          .replace(/[（(]\s*\d+\s*\/\s*\d+\s*[)）]/g, '').trim();
        // Split only at top-level separators, preserving notes such as 冰封(2回合).
        const parts = [];
        let start = 0, nesting = 0;
        for (let i = 0; i <= details.length; i++) {
          const ch = details[i];
          if (ch && /[（(\[【]/.test(ch)) nesting++;
          else if (ch && /[)）\]】]/.test(ch)) nesting = Math.max(0, nesting - 1);
          if (i === details.length || (nesting === 0 && /[,，;；]/.test(ch))) {
            const part = details.slice(start, i).trim();
            if (part) parts.push(part);
            start = i + 1;
          }
        }
        let direction = null;
        const notes = [];
        for (const part of parts) {
          const facing = /^面向\s*[:：]?\s*[\[【]?\s*(正向|负向|負向|正|负|負|→|←|\+|-)\s*[\]】]?\s*$/.exec(part);
          if (facing) direction = /^(负|負|←|-)/.test(facing[1]) ? -1 : 1;
          else notes.push(part);
        }
        units.push({name: name || fullName, fullName, faction, factionLabel, position: Number(match[1]), direction,
          mc: mcMatch ? mcMatch[1] : null, count: countMatch ? `${countMatch[1]}/${countMatch[2]}` : null, notes});
      }
      return units;
    }

    function parseAxisBounds(rows) {
      for (const row of rows) {
        const match = row.match(/坐[标標][范範][围圍]\s*[:：]\s*[\[【(（]?\s*([+-]?\d+)\s*(?:~|～|,|，|至|—|–|-)\s*([+-]?\d+)\s*[\]】)）]?/);
        if (match) {
          const min = Number(match[1]), max = Number(match[2]);
          if (Number.isSafeInteger(min) && Number.isSafeInteger(max) && min <= max) return {min, max};
        }
      }
      return null;
    }

    function parseAxisRanges(rows) {
      const result = [];
      for (const row of rows) {
        const markers = [...row.matchAll(/覆[盖蓋][区區][间間]\s*[:：]?\s*/g)];
        for (let i = 0; i < markers.length; i++) {
          const marker = markers[i];
          const start = marker.index + marker[0].length;
          const tail = row.slice(start, i + 1 < markers.length ? markers[i + 1].index : undefined);
          let rest = tail;
          const intervals = [];
          while (true) {
            const interval = rest.match(/^\s*[\[【(（]\s*([+-]?\d+)\s*[,，~～至]\s*([+-]?\d+)\s*[\]】)）]/);
            if (!interval) break;
            const low = Number(interval[1]), high = Number(interval[2]);
            if (Number.isSafeInteger(low) && Number.isSafeInteger(high) && low <= high) intervals.push([low, high]);
            rest = rest.slice(interval[0].length);
            const union = rest.match(/^\s*(?:∪|[Uu]|、|\+)\s*/);
            if (!union) break;
            rest = rest.slice(union[0].length);
          }
          if (!intervals.length) continue;
          const prefix = row.slice(0, marker.index);
          const namedAreas = [...prefix.matchAll(/[（(]\s*释放者\s*[:：]/g)];
          const caster = prefix.match(/释放者\s*[:：]\s*([^|,，]+)/);
          const shape = prefix.match(/形状\s*[:：]\s*([^|]+)/);
          const type = prefix.match(/类型\s*[:：]\s*([^|]+)/);
          let label;
          if (namedAreas.length) {
            const nameEnd = namedAreas[namedAreas.length - 1].index;
            let nameStart = 0, depth = 0;
            for (let j = 0; j < nameEnd; j++) {
              if (/[（(]/.test(prefix[j])) depth++;
              else if (/[)）]/.test(prefix[j])) depth = Math.max(0, depth - 1);
              else if (depth === 0 && /[|,:：，]/.test(prefix[j])) nameStart = j + 1;
            }
            label = axisCleanName(prefix.slice(nameStart, nameEnd));
          }
          else {
            const parts = [];
            if (caster) parts.push(axisCleanName(caster[1].replace(/[（(]\s*位置[\s\S]*$/, '')));
            if (shape || type) parts.push(axisCleanName((shape || type)[1]));
            label = parts.join(' · ') || `范围 ${result.length + 1}`;
          }
          const remaining = tail.match(/剩[余餘]\s*(?:回合\s*[:：]?\s*)?[\[【]?\s*(\d+)\s*[\]】]?\s*(?:回合)?/);
          const turns = remaining ? Number(remaining[1]) : null;
          result.push({label, intervals, turns});
        }
      }
      return result;
    }

    // Custom and production headings do not start combat rounds. Only known
    // combat phases end preparation, always within this same action_info.
    function isCombatStageBoundary(title) {
      return /^(?:回合[结結]算|[战戰][况況][总總][览覽]|行[动動][顺順]序|[战戰][术術][动動]作(?:\s*[-—–－]\s*[^()（）]+)?|攻[击擊]行[动動]|[伤傷]害基[准準][计計]算|[结結]算清[单單]|[状狀][态態][维維][护護]|回合[结結]束|[战戰]意判定|[战戰][斗鬥][结結]算|[经經][验驗][结結]算)(?:\s*[（(].*[)）])?$/.test(title);
    }

    function isPreparationAxis(section, sections) {
      for (let i = sections.indexOf(section) - 1; i >= 0; i--) {
        const title = sections[i].stageType;
        if (/^(?:[战戰]前[资資]源推演|[资資]源[总總][结結])$/.test(title)) return true;
        if (isCombatStageBoundary(title)) return false;
      }
      return false;
    }

    function buildBattleAxis(section, sections) {
      const axisRows = section.rows.filter(row => /位置[轴軸]\s*[:：]/.test(row));
      if (!axisRows.length) return null;
      const units = axisRows.flatMap(parseAxisUnits).sort((a, b) => a.position - b.position);
      if (!units.length) return null;
      const rangeRows = [...section.rows];
      const rangeSections = [];
      const index = sections.indexOf(section);
      for (let i = index + 1; i < sections.length && /^[范範][围圍][参參]考/.test(sections[i].stageType); i++) {
        rangeRows.push(...sections[i].rows);
        if (parseAxisRanges(sections[i].rows).length) rangeSections.push(sections[i]);
      }
      const ranges = parseAxisRanges(rangeRows);
      const declared = parseAxisBounds(section.rows) || parseAxisBounds(sections.flatMap(item => item.rows));
      const positions = units.map(unit => unit.position);
      const edges = ranges.flatMap(range => range.intervals.flat());
      const min = declared ? Math.min(declared.min, ...positions) : Math.min(...positions, ...edges);
      const max = declared ? Math.max(declared.max, ...positions) : Math.max(...positions, ...edges);
      // Keep exceptional unbounded text readable without creating enormous DOM grids.
      if (!Number.isSafeInteger(max - min) || max - min > 200) return null;
      const caption = /回合[结結]束/.test(section.stageType) ? '回合末站位' : /站位/.test(section.stageType) ? (isPreparationAxis(section, sections) ? '战前站位' : '回合初站位') : '当前站位';
      return {units, ranges, min, max, caption, declared, axisRows, rangeSections};
    }

    function createBattleAxis(model) {
      const make = (tag, className, text) => {
        const element = document.createElement(tag);
        if (className) element.className = className;
        if (text !== undefined) element.textContent = text;
        return element;
      };
      const root = make('div', 'battle-axis');
      const meta = make('div', 'axis-meta');
      meta.append(make('span', 'axis-caption', model.caption));
      meta.append(make('span', 'axis-bounds', `${model.declared ? '坐标范围' : '当前分布'} ${model.min} ～ ${model.max}`));
      root.append(meta);
      const toolbar = make('div', 'axis-toolbar');
      const selectors = [];
      for (const title of ['测距起点', '测距目标']) {
        const label = make('label', '', title);
        const select = make('select', 'axis-select');
        select.setAttribute('aria-label', `选择${title}单位`);
        model.units.forEach((unit, index) => {
          const option = make('option', '', `${unit.factionLabel ? '【' + unit.factionLabel + '】' : ''}${unit.fullName}（位置 ${unit.position}）`);
          option.value = String(index);
          select.append(option);
        });
        label.append(select);
        selectors.push(select);
        toolbar.append(label);
      }
      selectors[1].value = String(model.units.length - 1);
      root.append(toolbar);
      const readout = make('div', 'axis-readout');
      readout.setAttribute('aria-live', 'polite');
      root.append(readout);
      const scrollHint = make('div', 'axis-scroll-hint', '↔ 左右滑动查看战场');
      scrollHint.hidden = true;
      root.append(scrollHint);
      const scroll = make('div', 'axis-scroll');
      scroll.setAttribute('role', 'region');
      scroll.setAttribute('aria-label', '站位坐标轴，可横向滚动');
      scroll.tabIndex = 0;
      const width = (model.max - model.min + 1) * 88;
      const track = make('div', 'axis-track');
      const count = model.max - model.min + 1;
      track.style.gridTemplateColumns = `repeat(${count}, minmax(88px, 1fr))`;
      track.style.minWidth = `${width}px`;
      const buttons = [];
      const cells = [];
      for (let position = model.min; position <= model.max; position++) {
        const cell = make('div', 'axis-cell');
        cell.dataset.position = String(position);
        cells.push(cell);
        const stack = make('div', 'axis-stack');
        model.units.forEach((unit, index) => {
          if (unit.position !== position) return;
          const button = make('button', 'axis-unit');
          button.type = 'button';
          button.dataset.unit = String(index);
          if (unit.faction) button.dataset.faction = unit.faction;
          button.setAttribute('aria-label', `${unit.factionLabel ? unit.factionLabel + '，' : ''}${unit.fullName}，位置${position}${unit.direction ? '，面向' + (unit.direction > 0 ? '正向' : '负向') : ''}${unit.notes.length ? '，' + unit.notes.join('，') : ''}，选择为测距目标`);
          const markers = make('span', 'axis-selection-markers');
          const originMarker = make('span', 'axis-selection-marker axis-origin-marker', '起点');
          const targetMarker = make('span', 'axis-selection-marker axis-target-marker', '目标');
          originMarker.hidden = true;
          targetMarker.hidden = true;
          markers.append(originMarker, targetMarker);
          button.append(markers);
          if (unit.factionLabel) button.append(make('span', 'axis-faction-label', unit.factionLabel));
          const unitName = make('span', 'axis-unit-name', unit.name);
          if (unit.mc !== null) unitName.append(MCNameBadge.badge(document, unit.mc));
          button.append(unitName);
          if (unit.direction !== null) button.append(make('span', 'axis-facing', unit.direction > 0 ? '→' : '←'));
          if (unit.count !== null || unit.notes.length) {
            const tags = make('span', 'axis-unit-tags');
            if (unit.count !== null) tags.append(make('span', '', unit.count));
            unit.notes.forEach(note => tags.append(make('span', 'axis-unit-note', note)));
            button.append(tags);
          }
          button.addEventListener('click', () => {selectors[1].value = String(index); update(true);});
          buttons.push(button);
          stack.append(button);
        });
        cell.append(stack, make('div', 'axis-tick', String(position)));
        track.append(cell);
      }
      scroll.append(track);
      const rangeButtons = [];
      let activeRange = null;
      const coverageNote = make('div', 'axis-coverage-note', '范围仅标示位置覆盖，实际受影响目标以战斗判定为准。');
      coverageNote.setAttribute('aria-live', 'polite');
      function selectRange(index) {
        activeRange = activeRange === index ? null : index;
        rangeButtons.forEach((button, buttonIndex) => button.setAttribute('aria-pressed', buttonIndex === activeRange ? 'true' : 'false'));
        const range = activeRange === null ? null : model.ranges[activeRange];
        for (const cell of cells) {
          const position = Number(cell.dataset.position);
          const covered = !!range && range.intervals.some(([low, high]) => position >= low && position <= high);
          cell.classList.toggle('axis-covered', covered);
          if (covered) cell.dataset.rangePattern = String(activeRange % 3);
          else delete cell.dataset.rangePattern;
        }
        coverageNote.textContent = `${range ? `已突出范围 ${activeRange + 1}「${range.label}」覆盖的位置。再次点击可取消。` : ''}范围仅标示位置覆盖，实际受影响目标以战斗判定为准。`;
        MCNameBadge.decorate(coverageNote);
      }
      if (model.ranges.length) {
        const ranges = make('div', 'axis-ranges');
        ranges.style.minWidth = `${width}px`;
        model.ranges.forEach((range, index) => {
          const region = make('button', 'axis-region');
          region.type = 'button';
          region.dataset.rangePattern = String(index % 3);
          region.setAttribute('aria-pressed', 'false');
          const intervals = range.intervals.map(([low, high]) => `[${low}, ${high}]`).join(' ∪ ');
          const rangeLabel = make('span', 'axis-region-label');
          rangeLabel.append(make('span', 'axis-range-number', String(index + 1)), document.createTextNode(` ${range.label} · 覆盖 ${intervals}${range.turns !== null ? ` · 剩余 ${range.turns} 回合` : ''}`));
          region.append(rangeLabel);
          region.setAttribute('aria-label', `范围 ${index + 1}，${range.label}，覆盖 ${intervals}${range.turns !== null ? `，剩余 ${range.turns} 回合` : ''}，点击突出覆盖位置`);
          const lane = make('span', 'axis-range-track');
          lane.setAttribute('aria-hidden', 'true');
          for (const [low, high] of range.intervals) {
            const start = Math.max(low, model.min), end = Math.min(high, model.max);
            if (start > end) continue;
            const segment = make('span', 'axis-range-segment');
            segment.style.left = `${(start - model.min) / count * 100}%`;
            segment.style.width = `${(end - start + 1) / count * 100}%`;
            lane.append(segment);
          }
          region.append(lane);
          region.addEventListener('click', () => selectRange(index));
          rangeButtons.push(region);
          ranges.append(region);
        });
        scroll.append(ranges);
      }
      root.append(scroll);
      if (model.ranges.length) root.append(coverageNote);
      const resize = new ResizeObserver(entries => {
        const size = entries[0].contentRect.width;
        if (size > 0) scroll.style.setProperty('--axis-view-width', `${size}px`);
        scrollHint.hidden = scroll.scrollWidth <= scroll.clientWidth + 1;
      });
      resize.observe(scroll);
      const distanceName = distance => distance === 0 ? '贴身' : distance <= 2 ? '近程' : distance <= 5 ? '中程' : distance <= 10 ? '远程' : '超距';
      function revealTarget() {
        const target = buttons.find(button => button.dataset.unit === selectors[1].value);
        if (!target) return;
        const viewport = scroll.getBoundingClientRect();
        const card = target.getBoundingClientRect();
        const padding = 7;
        let left = scroll.scrollLeft;
        if (card.left < viewport.left + padding) left += card.left - viewport.left - padding;
        else if (card.right > viewport.right - padding) left += card.right - viewport.right + padding;
        // Only move the horizontal viewport; never call scrollIntoView on the page.
        scroll.scrollLeft = left;
      }
      function update(reveal = false) {
        const a = model.units[Number(selectors[0].value)];
        const b = model.units[Number(selectors[1].value)];
        const distance = Math.abs(a.position - b.position);
        const nameTag = unit => {
          const tag = make('span', 'axis-readout-unit', `${unit.factionLabel ? '【' + unit.factionLabel + '】' : ''}${unit.name}`);
          if (unit.mc !== null) tag.append(MCNameBadge.badge(document, unit.mc));
          if (unit.faction) tag.dataset.faction = unit.faction;
          return tag;
        };
        readout.replaceChildren(nameTag(a), document.createTextNode(' → '), nameTag(b),
          document.createTextNode(`：距离 ${distance}（${distanceName(distance)}）${b.count !== null ? ` · ${b.count}` : ''}`));
        MCNameBadge.decorate(readout);
        selectors.forEach((select, i) => {
          const faction = (i === 0 ? a : b).faction;
          if (faction) select.dataset.faction = faction;
          else delete select.dataset.faction;
          MCNameBadge.syncSelect(select);
        });
        for (const button of buttons) {
          const isTarget = button.dataset.unit === selectors[1].value;
          const isOrigin = button.dataset.unit === selectors[0].value;
          button.setAttribute('aria-pressed', isTarget ? 'true' : 'false');
          button.classList.toggle('axis-origin', isOrigin);
          button.querySelector('.axis-origin-marker').hidden = !isOrigin;
          button.querySelector('.axis-target-marker').hidden = !isTarget;
        }
        if (reveal) revealTarget();
      }
      selectors[0].addEventListener('change', () => update());
      selectors[1].addEventListener('change', () => update(true));
      update();
      return root;
    }

    // View controls only change presentation; every original row stays available.
    function resourceUnitInfo(row, section, snapshotUnits) {
      if (!/^(?:战况总览|戰況總覽|回合结束|回合結束|资源总结|資源總結)$/.test(section.stageType)) return null;
      const match = row.match(/^(.+?)\s*[:：]\s*(?=(?:HP|MP|SP)\b)/);
      if (!match) return null;
      const markedName = match[1].trim();
      const explicit = markedName.match(/^【\s*(蓝方|藍方|红方|紅方)\s*】\s*/);
      const clean = value => axisCleanName(value).replace(/\s+/g, '').replace(/（/g, '(').replace(/）/g, ')').replace(/＝/g, '=');
      const name = axisCleanName(explicit ? markedName.slice(explicit[0].length) : markedName);
      let faction = explicit ? (/^[蓝藍]/.test(explicit[1]) ? 'blue' : 'red') : null;
      if (!explicit) {
        const units = snapshotUnits;
        const exact = units.filter(unit => clean(unit.fullName) === clean(name));
        const candidates = exact.length ? exact : units.filter(unit => clean(unit.name) === clean(name));
        if (candidates.length === 1) faction = candidates[0].faction;
      }
      return {name, faction, rest: row.slice(match[0].length)};
    }

    function presentationRowKind(row, section, axisModel) {
      if (/^(?:行动顺序|行動順序)$/.test(section.stageType) && section.rows.some(item => /^序列\s*[:：]/.test(item)) && !/^序列\s*[:：]/.test(row)) return 'initiative';
      if (axisModel && /^持续性[区區]域\/[环環]境\s*[:：]/.test(row) && parseAxisRanges([row]).length) return 'area';
      if (/^[结結]算清[单單]/.test(section.stageType) && /^(?:掷骰|擲骰|命中加值|闪避减值|閃避減值|伤害修正|傷害修正|DR修正|巨兽范围承伤|巨獸範圍承傷|集群普攻|普通集群范围结算|巨兽集群范围结算)\s*(?:[:：（(])/.test(row)) return 'calculation';
      if (/^攻[击擊]行[动動]/.test(section.stageType) && /^(?:范围消耗计算|範圍消耗計算)\s*[:：]/.test(row)) return 'calculation';
      return 'normal';
    }

    function renderPanel(panel, containerSelector, append = false) {
      const $container = $(containerSelector);
      if (!append) $container.empty();
      const models = new Map(panel.sections.map(section => [section, buildBattleAxis(section, panel.sections)]));
      const visualizedReferences = new Set();
      const referenceNumbers = new Map();
      panel.sections.forEach((section, index) => {
        if (!models.get(section)) return;
        let number = parseAxisRanges(section.rows).length + 1;
        for (let i = index + 1; i < panel.sections.length && /^[范範][围圍][参參]考/.test(panel.sections[i].stageType); i++) {
          const rangeCount = parseAxisRanges(panel.sections[i].rows).length;
          if (rangeCount) {
            visualizedReferences.add(panel.sections[i]);
            referenceNumbers.set(panel.sections[i], rangeCount === 1 ? String(number) : `${number}–${number + rangeCount - 1}`);
            number += rangeCount;
          }
        }
      });
      const managedPanels = [];
      let hasDetails = false;
      panel.sections.forEach((section, sectionIndex) => {
        const config = _.get(PanelConfig, section.stageType, {icon: 'fa-solid fa-circle-info', color: '#e8d5b7'});
        const $panel = $('<div class="action-panel">').attr('data-section', section.title);
        const isInitiative = /^(?:行动顺序|行動順序)$/.test(section.stageType) && section.rows.some(row => /^序列\s*[:：]/.test(row));
        if (isInitiative) $panel.addClass('initiative-panel');
        const $header = $('<button type="button" class="panel-header" aria-expanded="true">');
        $header.append($('<i class="panel-icon">').addClass(config.icon).css('color', config.color).attr('aria-hidden', 'true'));
        $header.append($('<span class="panel-title">').text(section.displayTitle));
        if (referenceNumbers.has(section)) $header.append($('<span class="panel-range-number">').text(referenceNumbers.get(section)));
        const $hint = $('<span class="panel-expand-hint">');
        $header.append($hint, $('<i class="panel-toggle fa-solid fa-chevron-down" aria-hidden="true">'));
        const $content = $('<div class="panel-content">').attr('id', `section-content-${sectionIndex}`);
        $header.attr('aria-controls', `section-content-${sectionIndex}`);
        const axisModel = models.get(section);
        let snapshotUnits = section.rows.flatMap(parseAxisUnits);
        // Opening resources may precede their matching starting-position section
        // within this same action_info; never borrow another preparation or round.
        if (!snapshotUnits.length && /^(?:战况总览|戰況總覽|资源总结|資源總結)$/.test(section.stageType)) {
          const preparationSummary = /^(?:资源总结|資源總結)$/.test(section.stageType);
          for (let i = sectionIndex + 1; i < panel.sections.length; i++) {
            const next = panel.sections[i];
            if (/^(?:回合[结結]束|回合[结結]算|[战戰][况況][总總][览覽]|[战戰]前[资資]源推演|[资資]源[总總][结結]|[战戰][斗鬥][结結]算|[经經][验驗][结結]算)$/.test(next.stageType)) break;
            if (/^站位[与與]距[离離]$/.test(next.stageType)) {
              snapshotUnits = next.rows.flatMap(parseAxisUnits);
              break;
            }
            if (preparationSummary && isCombatStageBoundary(next.stageType)) break;
          }
        }
        const $axis = axisModel ? $(createBattleAxis(axisModel)) : null;
        if ($axis) $content.append($axis);
        const secondaryRows = [];
        const detailKinds = new Set();
        section.rows.forEach(row => {
          const $row = $('<div class="data-row">');
          const resource = resourceUnitInfo(row, section, snapshotUnits);
          if (resource) {
            $row.addClass('unit-resource-row');
            const $name = $('<span class="resource-unit-name">').text(resource.name + ':');
            if (resource.faction) {
              $row.attr('data-faction', resource.faction);
              $name.attr('data-faction', resource.faction);
              $name.prepend($('<span class="resource-faction-label">').text(resource.faction === 'blue' ? '蓝方' : '红方'));
            }
            $row.append($name, beautifyRow(resource.rest));
          } else {
            $row.html(beautifyRow(row));
          }
          if (/^(?:最终伤害|最終傷害|状态施加|狀態施加|状态效果|狀態效果|集群减员|集群減員|是否存活|检定结果|檢定結果)\s*[:：（(]/.test(row)) $row.addClass('outcome-row');
          if (/^(?:最终伤害|最終傷害)\s*[:：]/.test(row)) $row.addClass('damage-outcome');
          if (axisModel && axisModel.axisRows.includes(row)) {
            $('<details class="axis-raw"><summary>原始站位</summary></details>').append($row).appendTo($axis);
          } else {
            const kind = presentationRowKind(row, section, axisModel);
            if (kind !== 'normal') {
              $row.addClass('secondary-row').attr('data-detail-kind', kind);
              secondaryRows.push($row);
              detailKinds.add(kind);
            }
            $content.append($row);
          }
        });
        const collapseInCompact = /^(?:伤害基准计算|傷害基準計算)$/.test(section.stageType) || visualizedReferences.has(section);
        let $detailsButton = null;
        let detailsOpen = false;
        let setRowsOpen = null;
        if (secondaryRows.length) {
          const label = detailKinds.size === 1 && detailKinds.has('area') ? '区域详情' : '计算明细';
          if (!isInitiative) $detailsButton = $('<button type="button" class="row-details-toggle">');
          setRowsOpen = open => {
            detailsOpen = open;
            secondaryRows.forEach($row => $row.prop('hidden', !open));
            if ($detailsButton) $detailsButton.attr('aria-expanded', String(open)).text(`${open ? '收起' : '展开'}${label}（${secondaryRows.length}行）`);
          };
          if ($detailsButton) {
            $detailsButton.on('click', () => setRowsOpen(!detailsOpen));
            $content.append($detailsButton);
          }
        }
        const setPanelOpen = open => {
          $header.attr('aria-expanded', String(open)).toggleClass('collapsed', !open);
          $content.prop('hidden', !open);
          $hint.text(open ? '' : '点按展开');
        };
        $header.on('click', () => setPanelOpen($header.attr('aria-expanded') !== 'true'));
        const $headerBar = $('<div class="panel-header-bar">').append($header);
        $panel.append($headerBar, $content);
        $container.append($panel);
        if (collapseInCompact || secondaryRows.length) hasDetails = true;
        managedPanels.push({setPanelOpen, collapseInCompact, setRowsOpen, $axis});
      });

      const setView = full => {
        $container.attr('data-view', full ? 'full' : 'compact');
        managedPanels.forEach(item => {
          item.setPanelOpen(full || !item.collapseInCompact);
          if (item.setRowsOpen) item.setRowsOpen(full);
          if (item.$axis) item.$axis.find('.axis-raw').prop('open', full);
        });
        $container.find('.view-mode-button').each(function() {
          $(this).attr('aria-pressed', String($(this).attr('data-view') === (full ? 'full' : 'compact')));
        });
      };
      if (hasDetails) {
        const $toolbar = $('<div class="view-toolbar" role="group" aria-label="战斗信息显示方式">');
        [['compact', '简洁'], ['full', '完整']].forEach(([value, label]) => {
          const $button = $('<button type="button" class="view-mode-button">').attr('data-view', value).text(label);
          $button.on('click', () => setView(value === 'full'));
          $toolbar.append($button);
        });
        const $initiativeHeader = $container.find('.initiative-panel .panel-header-bar').first();
        const $viewHeader = $initiativeHeader.length ? $initiativeHeader : $container.find('.panel-header-bar').first();
        $viewHeader.addClass('has-view-controls').append($toolbar);
      }
      // Only the displayed DOM changes. Protocol text, unit models and stage IDs remain intact.
      MCNameBadge.decorate($container[0]);
      $container[0].querySelectorAll('.axis-select').forEach(select => MCNameBadge.enhanceSelect(select));
      setView(false);
    }

    $(() => {
      const panel = parseActionInfo(battleText);
      renderPanel(panel, '#content');
    });
  </script>
</body>
</html>
